/**
 * Organizes images into "Year" folders and prepends Date and Location to the name.
 * Processes top-level files and sub-folders (excluding "Processed Photos").
 * Includes logic for estimating dates from folder names for "0000" year metadata.
 */
function organizePhotosFinal() {
  const sourceFolderId = '1gD3a9TDU76wKuJGenl7pDxoxA93f16Oc';
  const sourceFolder = DriveApp.getFolderById(sourceFolderId);

  // 1. Setup Processed Photos root and standard subfolders
  const processedRoot = getOrCreateFolder(sourceFolder, "Processed Photos");
  const scansFolder = getOrCreateFolder(processedRoot, "Potential Scans");

  const allowedTypes = [
    'image/png', 'image/jpeg', 'image/bmp', 'image/tiff', 
    'application/pdf', 'image/gif', 'image/heif', 'image/heic'
  ];

  // 2. Process files at the top level
  processFolderFiles(sourceFolder, processedRoot, scansFolder, allowedTypes);

  // 3. Process sub-folders
  const subFolders = sourceFolder.getFolders();
  while (subFolders.hasNext()) {
    let subFolder = subFolders.next();

    // Skip the output directory to avoid infinite loops
    if (subFolder.getName() === "Processed Photos") continue;

    processFolderFiles(subFolder, processedRoot, scansFolder, allowedTypes);
  }
}

/**
 * Iterates through files in a given folder and applies organization logic.
 */
function processFolderFiles(currentFolder, processedRoot, scansFolder, allowedTypes) {
  const files = currentFolder.getFiles();
  const folderName = currentFolder.getName();
  const isSixDigitFolder = /^\d{6}_\d{4}$/.test(folderName);

  while (files.hasNext()) {
    let file = files.next();
    if (allowedTypes.indexOf(file.getMimeType()) === -1) continue;

    try {
      let driveFile = Drive.Files.get(file.getId(), {fields: 'imageMediaMetadata, md5Checksum'});
      let meta = driveFile.imageMediaMetadata;
      let currentMd5 = driveFile.md5Checksum;
      let targetFolder;
      let newName = file.getName();

      if (meta && meta.date) {
        let year = meta.date.substring(0, 4);
        let datePrefix = meta.date.substring(0, 10).replace(/:/g, '');

        // 4. Handle "0000" year date estimation
        if (year === "0000" && isSixDigitFolder) {
          let estimatedYear = "20" + folderName.substring(0, 2);
          targetFolder = getOrCreateFolder(processedRoot, estimatedYear + "APPROX");
        } else {
          targetFolder = getOrCreateFolder(processedRoot, year);
        }

        let locationString = "Unknown";
        if (meta.location && meta.location.latitude && meta.location.longitude) {
          locationString = getAddressFromMapsService(meta.location.latitude, meta.location.longitude);
        }
        newName = `${datePrefix}_${locationString}_${file.getName()}`;
      } else {
        targetFolder = scansFolder;
      }

      // 5. Duplicate and Collision Handling
      if (handleDuplicates(file, newName, currentMd5, targetFolder)) continue;

      // Final move and rename
      file.setName(newName);
      file.moveTo(targetFolder);
      console.log(`Moved ${file.getName()} to ${targetFolder.getName()}`);

    } catch (e) {
      if (e.toString().includes("Quota exceeded")) return;
      console.error(`Error: ${file.getName()} - ${e.toString()}`);
    }
  }
}

/**
 * Checks for existing files by name and binary content.
 * Returns true if the file was trashed as a duplicate.
 */
function handleDuplicates(file, newName, currentMd5, targetFolder) {
  let existingFiles = targetFolder.getFilesByName(newName);
  while (existingFiles.hasNext()) {
    let existingFile = existingFiles.next();
    let existingMeta = Drive.Files.get(existingFile.getId(), {fields: 'md5Checksum'});

    if (existingFile.getId() === file.getId() || existingMeta.md5Checksum === currentMd5) {
      file.setTrashed(true);
      return true;
    }
  }
  return false;
}

/**
 * Utility to find or create a folder by name.
 */
function getOrCreateFolder(parent, name) {
  const search = parent.getFoldersByName(name);
  return search.hasNext() ? search.next() : parent.createFolder(name);
}

/**
 * Uses Google Apps Script Maps Service to reverse geocode coordinates.
 */
function getAddressFromMapsService(lat, lng) {
  let retries = 0;
  while (retries < 3) {
    try {
      const response = Maps.newGeocoder().reverseGeocode(lat, lng);
      if (response.status === 'OK' && response.results.length > 0) {
        let city = "", state = "", country = "";
        const components = response.results[0].address_components;
        for (let comp of components) {
          if (comp.types.includes("locality")) city = comp.short_name;
          if (comp.types.includes("administrative_area_level_1")) state = comp.short_name;
          if (comp.types.includes("country")) country = comp.short_name;
        }
        let location = (country === "US") ? `${city}_${state}` : `${city}_${country}`;
        return (location || "Unknown").replace(/\s+/g, '-');
      }
      break;
    } catch (e) {
      if (e.toString().includes("frequently")) {
        Utilities.sleep(2000);
        retries++;
      } else { throw e; }
    }
  }
  return "Unknown";
}
